using Godot;
using System;
using Settings=Godot.Collections.Dictionary;

public partial class TransformationWorkspaceOperations
{
    public void refresh(Control owner){owner.Set("_syncing",true);string path=owner.Get("path").AsString();Item<Label>(owner,"header").Text="TRANSFORMATION 2D / "+(path.Length>0?path.GetFile():"Untitled")+(Session(owner).Get("dirty").AsBool()?" •":"");var canvas=Item<Control>(owner,"canvas");foreach(var pair in owner.Get("tools").AsGodotDictionary())pair.Value.As<BaseButton>().SetPressedNoSignal(canvas.Get("tool").AsString()==pair.Key.AsString()&&!Flag(owner,"previewing"));refresh_components(owner);owner.Call("_refresh_properties");owner.Call("_refresh_tools");owner.Call("_refresh_keys");owner.Set("_syncing",false);}
    public void refresh_components(Control owner){var tree=Item<Tree>(owner,"components");tree.Clear();var root=tree.CreateItem();var components=Document(owner).Get("components").AsGodotArray();for(int index=components.Count-1;index>=0;index--){var item=components[index].As<Resource>();var row=tree.CreateItem(root);row.SetText(0,item.Get("title").AsString());row.SetMetadata(0,item.Get("id"));row.SetEditable(0,true);var state=Active(owner,item);if(state!=null)row.SetIcon(0,state.Get("artwork").AsGodotObject().Get("texture").As<Texture2D>());row.SetIconMaxWidth(0,30);row.AddButton(1,icon("eye",item.Get("visible").AsBool()),0,false,"Show / hide component");row.AddButton(2,icon("lock",item.Get("locked").AsBool()),1,false,"Lock / unlock component");foreach(var id in Session(owner).Get("selected").AsGodotArray())if(id.AsString()==item.Get("id").AsString()){row.Select(0);break;}}}
    public Texture2D icon(string kind,bool active){using var image=Image.CreateEmpty(20,20,false,Image.Format.Rgba8);image.Fill(new Color(0,0,0,0));var color=new Color(active?"78dfc5":"526877");if(kind=="eye"){for(int x=2;x<18;x++){int y=(int)Math.Round(4+5*Math.Sin((double)(x-2)/15*Math.PI),MidpointRounding.AwayFromZero);image.SetPixel(x,y,color);image.SetPixel(x,20-y,color);}image.FillRect(new Rect2I(9,8,3,5),color);}else{image.FillRect(new Rect2I(5,8,11,10),color);image.FillRect(new Rect2I(7,3,7,6),color);}return ImageTexture.CreateFromImage(image);}
    public void tree_selected(Control owner,TreeItem row,bool selected){if(Flag(owner,"_syncing"))return;string id=row.GetMetadata(0).AsString();var chosen=Session(owner).Get("selected").AsGodotArray();for(int index=chosen.Count-1;index>=0;index--)if(chosen[index].AsString()==id)chosen.RemoveAt(index);if(selected)chosen.Add(id);var canvasSelected=Item<Control>(owner,"canvas").Get("selected").AsGodotArray();canvasSelected.Clear();foreach(var value in chosen)canvasSelected.Add(value);Pending(owner);}
    public void rename_component(Control owner){var row=Item<Tree>(owner,"components").GetEdited();if(row==null)return;var item=Document(owner).Call("component",row.GetMetadata(0).AsString()).As<Resource>();string value=row.GetText(0).Trim();if(item==null||item.Get("locked").AsBool()||value.Length==0)return;Session(owner).Call("begin");item.Set("title",value);Session(owner).Call("commit","Rename component");}
    public void component_button(Control owner,TreeItem row,int id){var item=Document(owner).Call("component",row.GetMetadata(0).AsString()).As<Resource>();if(item==null)return;Session(owner).Call("begin");string field=id==0?"visible":"locked";item.Set(field,!item.Get(field).AsBool());Session(owner).Call("commit",id==0?"Component visibility":"Component lock");}
    public Settings ui_state(Control owner){var session=Session(owner);var canvas=Item<Control>(owner,"canvas");var timeline=Item<Control>(owner,"timeline");return new Settings {["selected"]=session.Get("selected").AsGodotArray().Duplicate(),["states"]=session.Get("edit_states").AsGodotDictionary().Duplicate(),["time"]=session.Get("playhead"),["previewing"]=owner.Get("previewing"),["zoom"]=canvas.Get("zoom"),["pan"]=canvas.Get("pan"),["loop"]=owner.Get("loop"),["onion"]=owner.Get("onion"),["timeline_x"]=timeline.Get("offset"),["timeline_y"]=timeline.Get("vertical"),["timeline_zoom"]=timeline.Get("pixels_per_second")};}
    public Settings capture_state(Control owner){finish_pending(owner);owner.Set("playing",false);return new Settings {["session"]=Session(owner),["path"]=owner.Get("path"),["ui"]=ui_state(owner)};}
    public double view_number(Settings ui,string name,double fallback){if(!ui.TryGetValue(name,out var value)||value.VariantType is not Variant.Type.Float and not Variant.Type.Int)return fallback;double number=value.AsDouble();return double.IsFinite(number)?number:fallback;}
}
